// Paths/cores extraídos do pacote simple-icons (MIT) uma única vez — mantidos
// aqui como dados locais para não puxar o pacote inteiro (~5MB) para o
// bundle do servidor só por um punhado dos milhares de ícones que ele expõe.
export interface TechIcon {
  title: string
  // Corresponde ao `slug` gerado por `slugify()` para as tecnologias reais
  // cadastradas no banco (ex: technology.slug) — usado para o lookup.
  slug: string
  // Sem hex = ícone monocromático (preto/cinza-escuro na marca oficial),
  // herda a cor do texto (currentColor) para não sumir no tema escuro.
  // Não se aplica a ícones com `svg` (cor já vem embutida no markup).
  hex?: string
  // Override só para o tema claro — usado quando a cor oficial (hex) é
  // clara demais e some contra o fundo claro da pill (ex: Drizzle, JavaScript).
  lightHex?: string
  // Override só para o tema escuro — usado quando a cor oficial (hex) é
  // escura/pouco saturada demais e some contra o fundo escuro da pill
  // (ex: PostgreSQL, cujo azul oficial 4169E1 tem contraste baixo no dark).
  darkHex?: string
  // Viewbox original do SVG da marca — só precisa informar quando != 24x24
  // (a maioria dos ícones do simple-icons já usa 0 0 24 24).
  viewBox?: string
  // Ícone de um path só, pintado via currentColor (padrão simple-icons).
  path?: string
  // Markup interno bruto (múltiplos paths/grupos com cor própria da marca) —
  // usado para SVGs oficiais colados diretamente (ex: logo com mais de uma
  // cor), que não fazem sentido forçar num único path com currentColor.
  svg?: string
}

