export function getTechIcon(slug: string): TechIcon | undefined {
  return TECH_ICONS.find(icon => icon.slug === slug)
}

// Curadoria de quem aparece no marquee da home (TechMarquee) — não é a lista
// inteira de TECH_ICONS, só os slugs abaixo, agrupados por tipo (mesmas
// categorias do formulário de projetos). Edite livremente para
// adicionar/remover/reordenar; o restante do catálogo continua disponível
// para os badges de tecnologia dos projetos.
export const MARQUEE_SLUGS: string[] = [
  // Frontend
  'nuxt',
  'vue-js',
  'next-js',
  'react',
  'typescript',
  'javascript',
  'html5',
  'css3',
  'tailwind-css',
  'shadcn-ui',
  'chart-js',
  // Backend
  'node-js',
  'express',
  'java',
  'spring-boot',
  'spring-mvc',
  // API
  'graphql',
  'openapi',
  // Banco de dados
  'postgresql',
  'mysql',
  // ORM
  'drizzle',
  // Cloud
  'aws',
  'google-cloud',
  'firebase',
  'vercel',
  'cloudflare',
  // DevOps
  'docker',
  'github-actions',
  'kubernetes',
  'jenkins',
  // Build
  'vite',
  // Testes
  'vitest',
  'cypress',
  'lighthouse',
  // IA
  'gemini',
  'claude',
  // Segurança
  'jwt',
  'google-oauth',
  // Pagamentos
  'stripe',
  'mercado-pago',
  // Versionamento
  'git',
  'github'
]

export function getMarqueeIcons(): TechIcon[] {
  return MARQUEE_SLUGS
    .map(slug => getTechIcon(slug))
    .filter((icon): icon is TechIcon => icon !== undefined)
}
